### 🧩 **Tetris Java Kodini Yozish (Console-based)**
```java
import java.util.Scanner;

public class Tetris {
    static final int BOARD_WIDTH = 10;
    static final int BOARD_HEIGHT = 20;
    static int[][] board = new int[BOARD_HEIGHT][BOARD_WIDTH];
    static Piece currentPiece;
    static int score = 0;

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        initBoard();
        currentPiece = new Piece();
        boolean gameOver = false;

        while (!gameOver) {
            printBoard();
            System.out.print("Harakat (W/A/S/D): ");
            char input = scanner.next().charAt(0);

            switch (input) {
                case 'a': currentPiece.moveLeft(); break;
                case 'd': currentPiece.moveRight(); break;
                case 's': currentPiece.moveDown(); break;
                case 'w': currentPiece.rotate(); break;
            }

            if (!currentPiece.moveDown()) {
                lockPiece();
                clearLines();
                currentPiece = new Piece();
                if (!canPlacePiece()) {
                    gameOver = true;
                }
            }
        }
        System.out.println("O'yin tugadi! Skor: " + score);
    }

    static void initBoard() {
        for (int i = 0; i < BOARD_HEIGHT; i++) {
            for (int j = 0; j < BOARD_WIDTH; j++) {
                board[i][j] = 0;
            }
        }
    }

    static void printBoard() {
        for (int i = 0; i < BOARD_HEIGHT; i++) {
            for (int j = 0; j < BOARD_WIDTH; j++) {
                if (board[i][j] == 1) System.out.print("■ ");
                else System.out.print("  ");
